class Solution {
    int moves[8][2] = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};
public:
    std::vector<std::vector<int>> checkValidGrid(int m, int n, int r, int c) {
        std::vector<std::vector<int>> board(m, std::vector<int>(n, -1));
        board[r][c] = 0;
        auto get_deg = [&](int cr, int cc) {
            int cnt = 0;
            for (auto& mv : moves) {
                int nr = cr + mv[0], nc = cc + mv[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == -1) cnt++;
            }
            return cnt;
        };
        auto dfs = [&](auto& self, int cr, int cc, int step) -> bool {
            if (step == m * n) return true;
            std::vector<std::tuple<int, int, int>> cands;
            for (auto& mv : moves) {
                int nr = cr + mv[0], nc = cc + mv[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == -1) {
                    cands.push_back({get_deg(nr, nc), nr, nc});
                }
            }
            std::sort(cands.begin(), cands.end());
            for (auto& [_, nr, nc] : cands) {
                board[nr][nc] = step;
                if (self(self, nr, nc, step + 1)) return true;
                board[nr][nc] = -1;
            }
            return false;
        };
        dfs(dfs, r, c, 1);
        return board;
    }
};

class Solution {
    private final int[][] moves = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};

    public int[][] checkValidGrid(int m, int n, int r, int c) {
        int[][] board = new int[m][n];
        for (int[] row : board) Arrays.fill(row, -1);
        board[r][c] = 0;
        dfs(board, m, n, r, c, 1);
        return board;
    }

    private int getDeg(int[][] board, int m, int n, int cr, int cc) {
        int cnt = 0;
        for (int[] mv : moves) {
            int nr = cr + mv[0], nc = cc + mv[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == -1) cnt++;
        }
        return cnt;
    }

    private boolean dfs(int[][] board, int m, int n, int cr, int cc, int step) {
        if (step == m * n) return true;
        List<int[]> cands = new ArrayList<>();
        for (int[] mv : moves) {
            int nr = cr + mv[0], nc = cc + mv[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == -1) {
                cands.add(new int[]{getDeg(board, m, n, nr, nc), nr, nc});
            }
        }
        cands.sort(Comparator.comparingInt(a -> a[0]));
        for (int[] cand : cands) {
            int nr = cand[1], nc = cand[2];
            board[nr][nc] = step;
            if (dfs(board, m, n, nr, nc, step + 1)) return true;
            board[nr][nc] = -1;
        }
        return false;
    }
}

var checkValidGrid = function(m, n, r, c) {
    const board = Array.from({ length: m }, () => new Array(n).fill(-1));
    board[r][c] = 0;
    const moves = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]];
    function getDegree(cr, cc) {
        let cnt = 0;
        for (const [dr, dc] of moves) {
            const nr = cr + dr, nc = cc + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] === -1) cnt++;
        }
        return cnt;
    }
    function dfs(cr, cc, step) {
        if (step === m * n) return true;
        const cands = [];
        for (const [dr, dc] of moves) {
            const nr = cr + dr, nc = cc + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] === -1) {
                cands.push([getDegree(nr, nc), nr, nc]);
            }
        }
        cands.sort((a, b) => a[0] - b[0]);
        for (const [_, nr, nc] of cands) {
            board[nr][nc] = step;
            if (dfs(nr, nc, step + 1)) return true;
            board[nr][nc] = -1;
        }
        return false;
    }
    dfs(r, c, 1);
    return board;
};
